function slugify(text) {
  const base = String(text || "flashplay-game")
    .toLowerCase()
    .replace(/[^a-z0-9]+/g, "-")
    .replace(/^-+|-+$/g, "")
    .slice(0, 30);
  return `${base || "flashplay-game"}-${Date.now()}`;
}

const PREVIEW_BUFFER = Buffer.from(
  "iVBORw0KGgoAAAANSUhEUgAAAAEAAAABCAQAAAC1HAwCAAAAC0lEQVR42mP8/x8AAwMCAO9W8j8AAAAASUVORK5CYII=",
  "base64"
);

export class AIGamesPublisher {
  async publish({ request, route, generated }) {
    const slug = slugify(request.gameName || request.prompt);
    await uploadFile({
      endpoint: getConfigEndpoint(),
      gameFolder: slug,
      fileName: "config.json",
      mimeType: "application/json",
      fileData: JSON.stringify({ title: generated.title })
    });
    const indexUpload = await uploadFile({
      endpoint: getIndexEndpoint(),
      gameFolder: slug,
      fileName: "index.html",
      mimeType: "text/html",
      fileData: generated.html
    });
    await uploadFile({
      endpoint: getPreviewEndpoint(),
      gameFolder: slug,
      fileName: "preview.png",
      mimeType: "image/png",
      fileData: PREVIEW_BUFFER
    });

    return {
      slug,
      gameURL: `${getPublicGameBaseURL()}/${slug}`,
      rawURL:
        indexUpload.data?.downloadUrl ||
        indexUpload.data?.htmlUrl ||
        `https://raw.githubusercontent.com/brianclan/aigames/main/${slug}/index.html`,
      publisher: "aigames",
      route,
      title: generated.title
    };
  }
}

function getConfigEndpoint() {
  return process.env.AIGAMES_CONFIG_ENDPOINT || "https://www.idlab.top/xlabopenapi/github/aigames/config";
}

function getIndexEndpoint() {
  return process.env.AIGAMES_INDEX_ENDPOINT || "https://www.idlab.top/xlabopenapi/github/aigames/index";
}

function getPreviewEndpoint() {
  return process.env.AIGAMES_PREVIEW_ENDPOINT || "https://www.idlab.top/xlabopenapi/github/aigames/preview";
}

function getPublicGameBaseURL() {
  return (process.env.AIGAMES_PUBLIC_GAME_BASE_URL || "https://thenext.games/game").replace(/\/+$/, "");
}

async function uploadFile({ endpoint, gameFolder, fileName, mimeType, fileData }) {
  const formData = new FormData();
  formData.append("gameFolder", gameFolder);
  formData.append(
    "file",
    new Blob([fileData], { type: mimeType }),
    fileName
  );

  const response = await fetch(endpoint, {
    method: "POST",
    body: formData
  });
  if (!response.ok) {
    throw new Error(`aigames_upload_failed:${response.status}`);
  }

  const payload = await response.json();
  if (payload?.code !== 200) {
    throw new Error(`aigames_upload_invalid:${payload?.code ?? "unknown"}`);
  }
  return payload;
}

