import { spawn } from "node:child_process";
import { writeFile } from "node:fs/promises";

export class CodexProvider {
  async generate({ system, request }) {
    const instruction = buildInstruction({ system, request });
    const generated = await runGenerationChain({ system, request, instruction });
    const raw = generated.raw;
    const payload = pickGeneratedPayload(raw);
    if (!payload?.html) {
      throw new Error("codex_invalid_payload");
    }

    return {
      title: cleanTitle(payload.title, request),
      summary: cleanSummary(payload.summary, system),
      html: payload.html,
      provider: generated.provider,
      model: generated.model
    };
  }
}

function buildInstruction({ system, request }) {
  const gameName = request.gameName || "FlashPlay Game";
  const prompt = request.prompt || "做一个可以直接玩的手机小游戏";
  return [
    "你是 FlashPlay 的小游戏生成器。",
    `当前路由: ${system}`,
    "只返回一个严格 JSON 对象，不要 markdown，不要解释，不要代码块。",
    '只允许 3 个顶级字段: "title", "summary", "html"。',
    "title 必须是游戏名称。",
    "summary 必须是 1 句中文简介。",
    "html 必须是完整可运行的 index.html。",
    "输出必须适配手机竖屏，支持触摸与鼠标点击，且不依赖外部资源。",
    "必须包含完整 viewport 设置、无默认外边距、满屏布局。",
    "如果玩法适合 2D，就产出稳定的 2D H5 游戏。",
    "如果玩法强调 3D/空间/跑酷/赛车/第一人称，就产出更强展示感的 demo。",
    `游戏名: ${gameName}`,
    `用户需求: ${prompt}`
  ].join("\n");
}

function runCodexInstruction(instruction) {
  return new Promise((resolve, reject) => {
    const child = spawn(
      getCodexExecutable(),
      [
        "exec",
        "--disable",
        "plugins",
        "--json",
        "--skip-git-repo-check",
        "--sandbox",
        "read-only",
        "--model",
        getCodexModel(),
        instruction
      ],
      {
        env: buildCodexCLIEnv(),
        stdio: ["pipe", "pipe", "pipe"]
      }
    );

    let stdout = "";
    let stderr = "";
    let settled = false;
    const timeout = setTimeout(() => {
      if (settled) return;
      settled = true;
      const combined = [stdout, stderr].filter(Boolean).join("\n");
      writeDebugOutput(combined);
      child.kill("SIGTERM");
      setTimeout(() => {
        child.kill("SIGKILL");
      }, 3000);
      reject(new Error("codex_timeout"));
    }, getCodexTimeoutMS());

    child.stdout.on("data", chunk => {
      stdout += chunk.toString();
    });

    child.stderr.on("data", chunk => {
      stderr += chunk.toString();
    });

    child.on("error", async error => {
      if (settled) return;
      settled = true;
      clearTimeout(timeout);
      const combined = [stdout, stderr].filter(Boolean).join("\n");
      await writeDebugOutput(combined);
      reject(error);
    });

    child.on("close", async code => {
      if (settled) return;
      settled = true;
      clearTimeout(timeout);
      const combined = [stdout, stderr].filter(Boolean).join("\n");
      await writeDebugOutput(combined);
      if (!combined.trim()) {
        reject(new Error("codex_empty_output"));
        return;
      }
      const payload = pickGeneratedPayload(combined);
      if (payload?.html) {
        resolve(JSON.stringify(payload));
        return;
      }
      if (code !== 0) {
        reject(new Error(stderr || stdout || `codex_exit_${code}`));
        return;
      }
      resolve(combined);
    });

    child.stdin.end();
  });
}

function buildCodexCLIEnv() {
  const env = { ...process.env };
  delete env.OPENAI_API_KEY;
  delete env.OPENAI_BASE_URL;
  delete env.OPENAI_MODEL;
  delete env.KIMI_API_KEY;
  delete env.KIMI_BASE_URL;
  delete env.KIMI_MODEL;
  delete env.MOONSHOT_API_KEY;
  return env;
}

async function runOpenAIResponsesInstruction(instruction) {
  const response = await fetch(`${getOpenAIBaseURL()}/responses`, {
    method: "POST",
    headers: {
      "content-type": "application/json",
      authorization: `Bearer ${getOpenAIAPIKey()}`
    },
    body: JSON.stringify({
      model: getOpenAIModel(),
      input: instruction,
      text: {
        format: {
          type: "json_schema",
          name: "flashplay_game_payload",
          strict: true,
          schema: {
            type: "object",
            additionalProperties: false,
            required: ["title", "summary", "html"],
            properties: {
              title: { type: "string" },
              summary: { type: "string" },
              html: { type: "string" }
            }
          }
        }
      }
    })
  });

  if (!response.ok) {
    throw new Error(`openai_responses_failed:${response.status}`);
  }

  const payload = await response.json();
  const textOutput =
    payload.output_text ||
    payload.output?.flatMap(item => item.content || []).map(item => item.text).filter(Boolean).join("\n") ||
    "";
  if (!textOutput.trim()) {
    throw new Error("openai_responses_empty");
  }
  return textOutput;
}

async function runKimiChatInstruction({ system, request, instruction }) {
  const response = await fetch(`${getKimiBaseURL()}/chat/completions`, {
    method: "POST",
    headers: {
      "content-type": "application/json",
      authorization: `Bearer ${getKimiAPIKey()}`
    },
    body: JSON.stringify({
      model: getKimiModel(),
      temperature: 0.2,
      messages: [
        {
          role: "system",
          content: [
            "你是 FlashPlay 的小游戏生成器。",
            `当前路由: ${system}`,
            "你更擅长中文与代码生成。",
            "只返回严格 JSON，不要 markdown，不要解释，不要代码块。",
            '只允许 3 个顶级字段: "title", "summary", "html"。',
            "html 必须是完整可运行的 index.html，并适配手机竖屏与鼠标点击。"
          ].join("\n")
        },
        {
          role: "user",
          content: [
            `游戏名: ${request.gameName || "FlashPlay Game"}`,
            `用户需求: ${request.prompt || "做一个可以直接玩的手机小游戏"}`,
            "",
            instruction
          ].join("\n")
        }
      ]
    })
  });

  if (!response.ok) {
    throw new Error(`kimi_chat_failed:${response.status}`);
  }

  const payload = await response.json();
  const textOutput = payload.choices?.[0]?.message?.content || "";
  if (!String(textOutput).trim()) {
    throw new Error("kimi_chat_empty");
  }
  return textOutput;
}

async function runGenerationChain({ system, request, instruction }) {
  const attempts = [];

  for (const provider of getProviderOrder()) {
    try {
      if (provider === "codex-cli" && isCodexCLIEnabled()) {
        const raw = await runCodexWithRetry({ system, request, instruction });
        return {
          provider: "codex-cli",
          model: getCodexModel(),
          raw
        };
      }
      if (provider === "kimi" && getKimiAPIKey()) {
        return {
          provider: "kimi",
          model: getKimiModel(),
          raw: await runKimiChatInstruction({ system, request, instruction })
        };
      }
      if (provider === "openai" && getOpenAIAPIKey()) {
        return {
          provider: "openai",
          model: getOpenAIModel(),
          raw: await runOpenAIResponsesInstruction(instruction)
        };
      }
    } catch (error) {
      attempts.push(`${provider}:${String(error?.message || error)}`);
    }
  }

  throw new Error(attempts.length ? attempts.join(" | ") : "no_generation_provider_available");
}

function pickGeneratedPayload(text) {
  for (const candidate of collectPayloadCandidates(text)) {
    const normalized = normalizePayloadCandidate(candidate);
    if (normalized?.html) {
      return normalized;
    }
  }
  const html = extractHTMLDocument(text);
  if (html) {
    return { title: "", summary: "", html };
  }
  return null;
}

async function runCodexWithRetry({ system, request, instruction }) {
  const firstRaw = await runCodexInstruction(instruction);
  if (pickGeneratedPayload(firstRaw)?.html) {
    return firstRaw;

    return firstRaw;
  }

  if (!shouldRetryCodexPayload()) {
    return firstRaw;
  }

  const retryInstruction = buildRetryInstruction({ system, request });
  return runCodexInstruction(retryInstruction);
}

function buildRetryInstruction({ system, request }) {
  const gameName = request.gameName || "FlashPlay Game";
  const prompt = request.prompt || "做一个可以直接玩的手机小游戏";
  return [
    "重试生成。",
    `当前路由: ${system}`,
    "必须仅输出一个 JSON 对象，禁止额外文本。",
    "JSON 至少包含 html 字段，建议包含 title 和 summary。",
    "html 必须是完整 index.html，移动端竖屏，支持触摸和鼠标。",
    `游戏名: ${gameName}`,
    `用户需求: ${prompt}`
  ].join("\n");
}

function normalizePayloadCandidate(candidate) {
  if (!candidate || typeof candidate !== "object") {
    return null;
  }
  const html = pickFirstString([
    candidate.html,
    candidate.content,
    candidate.code,
    candidate.data?.html,
    candidate.output?.html
  ]);
  if (!html) {
    return null;
  }
  return {
    title: pickFirstString([candidate.title, candidate.name, candidate.data?.title]),
    summary: pickFirstString([candidate.summary, candidate.description, candidate.data?.summary]),
    html
  };
}

function pickFirstString(values) {
  for (const value of values) {
    if (typeof value === "string" && value.trim()) {
      return value;
    }
  }
  return "";
}

function extractHTMLDocument(text) {
  const input = String(text || "");
  const doc = input.match(/<!doctype\s+html[\s\S]*<\/html>/i);
  if (doc?.[0]) {
    return doc[0];
  }
  const html = input.match(/<html[\s\S]*<\/html>/i);
  return html?.[0] || "";
}

function collectPayloadCandidates(text) {
  const candidates = [];
  for (const candidate of extractJSONObjectCandidates(text)) {
    candidates.push(candidate);
    const payloadText = candidate?.payloads?.[0]?.text;
    if (typeof payloadText === "string") {
      candidates.push(...extractJSONObjectCandidates(payloadText));
    }
    const itemText = candidate?.item?.text;
    if (typeof itemText === "string") {
      candidates.push(...extractJSONObjectCandidates(itemText));
    }
    const messageText = candidate?.message?.content;
    if (typeof messageText === "string") {
      candidates.push(...extractJSONObjectCandidates(messageText));
    }
  }
  return candidates;
}

async function writeDebugOutput(text) {
  const debugPath =
    process.env.CODEX_DEBUG_OUTPUT_PATH ||
    ((process.env.CODEX_DEBUG_OUTPUT || "").toLowerCase() === "true"
      ? "/tmp/flashplay-codex-last-output.log"
      : "");
  if (!debugPath) {
    return;
  }
  await writeFile(debugPath, String(text || ""), "utf8").catch(() => {});
}

function extractJSONObjectCandidates(text) {
  const candidates = [];
  const input = String(text || "");
  const parsedWhole = tryParseJSON(stripCodeFence(input));
  if (parsedWhole) {
    candidates.push(parsedWhole);
  }
  for (let i = 0; i < input.length; i += 1) {
    if (input[i] !== "{") continue;
    let depth = 0;
    let inString = false;
    let escaped = false;
    for (let j = i; j < input.length; j += 1) {
      const char = input[j];
      if (inString) {
        if (escaped) {
          escaped = false;
          continue;
        }
        if (char === "\\") {
          escaped = true;
          continue;
        }
        if (char === "\"") {
          inString = false;
        }
        continue;
      }
      if (char === "\"") {
        inString = true;
        continue;
      }
      if (char === "{") depth += 1;
      if (char === "}") depth -= 1;
      if (depth === 0) {
        const maybeObject = input.slice(i, j + 1);
        const parsed = tryParseJSON(stripCodeFence(maybeObject));
        if (parsed) {
          candidates.push(parsed);
        }
        break;
      }
    }
  }
  return candidates;
}

function stripCodeFence(text) {
  return String(text || "")
    .replace(/^```(?:json)?/i, "")
    .replace(/```$/i, "")
    .trim();
}

function tryParseJSON(text) {
  try {
    return JSON.parse(text);
  } catch {
    return null;
  }
}

function cleanTitle(title, request) {
  return String(title || request.gameName || request.prompt || "FlashPlay Game")
    .trim()
    .slice(0, 48);
}

function cleanSummary(summary, system) {
  return String(summary || `由 ${system} + Codex 生成`).trim().slice(0, 120);
}

function getCodexExecutable() {
  return process.env.CODEX_EXECUTABLE || "codex";
}

function getCodexTimeoutMS() {
  return Number(process.env.CODEX_TIMEOUT_MS || 150_000);
}

function getCodexModel() {
  return process.env.CODEX_MODEL || "gpt-5.4";
}

function getOpenAIAPIKey() {
  return process.env.OPENAI_API_KEY || "";
}

function getOpenAIBaseURL() {
  return (process.env.OPENAI_BASE_URL || "https://api.openai.com/v1").replace(/\/+$/, "");
}

function getOpenAIModel() {
  return process.env.OPENAI_MODEL || getCodexModel();
}

function getKimiAPIKey() {
  return process.env.KIMI_API_KEY || process.env.MOONSHOT_API_KEY || "";
}

function getKimiBaseURL() {
  return (process.env.KIMI_BASE_URL || "https://api.moonshot.ai/v1").replace(/\/+$/, "");
}

function getKimiModel() {
  return process.env.KIMI_MODEL || "kimi-k2.5";
}

function isCodexCLIEnabled() {
  return (process.env.CODEX_CLI_ENABLED || "true").toLowerCase() !== "false";
}

function shouldRetryCodexPayload() {
  return (process.env.CODEX_RETRY_ON_INVALID_PAYLOAD || "true").toLowerCase() !== "false";
}

function getProviderOrder() {
  const raw = process.env.GENERATION_PROVIDER_ORDER || "codex-cli,kimi,openai";
  return raw
    .split(",")
    .map(item => item.trim().toLowerCase())
    .filter(Boolean);
}

