import "./config/load-env.mjs";
import http from "node:http";
import { GenerationGateway } from "./gateway/generation-gateway.mjs";
import { InMemoryTaskStore } from "./store/task-store.mjs";
import { SkillRouter } from "./routing/skill-router.mjs";
import { GameEngineProvider } from "./providers/game-engine-provider.mjs";
import { BuildGameProvider } from "./providers/build-game-provider.mjs";
import { CodexProvider } from "./providers/codex-provider.mjs";
import { AIGamesPublisher } from "./providers/aigames-publisher.mjs";

const PORT = Number(process.env.PORT || 18900);

const taskStore = new InMemoryTaskStore();
const codexProvider = new CodexProvider();
const gateway = new GenerationGateway({
  router: new SkillRouter(),
  taskStore,
  providers: {
    "game-engine": new GameEngineProvider({ codexProvider }),
    "build-game": new BuildGameProvider({ codexProvider })
  },
  publisher: new AIGamesPublisher()
});

const SERVICE_INFO = {
  ok: true,
  service: "flashplay-backend",
  port: PORT,
  routes: ["game-engine", "build-game"],
  provider: "codex",
  publisher: "aigames"
};

function sendJSON(res, statusCode, body) {
  res.writeHead(statusCode, { "content-type": "application/json; charset=utf-8" });
  res.end(JSON.stringify(body));
}

function readJSONBody(req) {
  return new Promise((resolve) => {
    let raw = "";
    req.on("data", chunk => {
      raw += chunk;
    });
    req.on("end", () => {
      try {
        resolve(JSON.parse(raw || "{}"));
      } catch {
        resolve({});
      }
    });
  });
}

function routeGenerationId(url) {
  const match = url.match(/^\/generations\/([^/]+)$/);
  return match?.[1] ?? null;
}

const server = http.createServer(async (req, res) => {
  if (req.method === "GET" && req.url === "/health") {
    sendJSON(res, 200, SERVICE_INFO);
    return;
  }

  if (req.method === "POST" && req.url === "/generations") {
    const payload = await readJSONBody(req);
    if (!String(payload.prompt || "").trim()) {
      sendJSON(res, 400, { ok: false, error: "prompt_required" });
      return;
    }
    const task = await gateway.createGeneration(payload);
    sendJSON(res, 202, task);
    return;
  }

  const generationId = typeof req.url === "string" ? routeGenerationId(req.url) : null;
  if (req.method === "GET" && generationId) {
    const task = taskStore.get(generationId);
    if (!task) {
      sendJSON(res, 404, { ok: false, error: "generation_not_found" });
      return;
    }
    sendJSON(res, 200, task);
    return;
  }

  sendJSON(res, 404, { ok: false, error: "not_found" });
});

server.listen(PORT, "127.0.0.1", () => {
  console.log(`[flashplay-backend] listening on http://127.0.0.1:${PORT}`);
});

