export async function runMinimaxChatInstruction({ system, request, instruction }) {
  const response = await fetch(`${getMinimaxBaseURL()}/chat/completions`, {
    method: "POST",
    headers: {
      "content-type": "application/json",
      authorization: `Bearer ${getMinimaxAPIKey()}`
    },
    body: JSON.stringify({
      model: getMinimaxModel(),
      temperature: getMinimaxTemperature(),
      response_format: { type: "json_object" },
      messages: [
        {
          role: "system",
          content: [
            "你是 FlashPlay 的小游戏生成器。",
            `当前路由: ${system}`,
            "只返回严格 JSON，不要 markdown，不要解释，不要代码块。",
            '只允许 3 个顶级字段: "title", "summary", "html"。',
            "title 必须是游戏名称。",
            "summary 必须是 1 句中文简介。",
            "html 必须是完整可运行的 index.html，并适配手机竖屏、触摸与鼠标点击。",
            "不要依赖外部图片、音频或无法离线访问的资源。"
          ].join("\n")
        },
        {
          role: "user",
          content: [
            `游戏名: ${request.gameName || "FlashPlay Game"}`,
            `用户需求: ${request.prompt || "做一个可以直接玩的手机小游戏"}`,
            "",
            instruction
          ].join("\n")
        }
      ]
    })
  });

  if (!response.ok) {
    throw new Error(`minimax_chat_failed:${response.status}`);
  }

  const payload = await response.json();
  const textOutput = payload.choices?.[0]?.message?.content || "";
  if (!String(textOutput).trim()) {
    throw new Error("minimax_chat_empty");
  }
  return textOutput;
}

export function getMinimaxAPIKey() {
  return process.env.MINIMAX_API_KEY || "";
}

export function getMinimaxBaseURL() {
  return (process.env.MINIMAX_BASE_URL || "https://api.minimax.io/v1").replace(/\/+$/, "");
}

export function getMinimaxModel() {
  return process.env.MINIMAX_MODEL || "MiniMax-M2.5";
}

function getMinimaxTemperature() {
  const value = Number(process.env.MINIMAX_TEMPERATURE || 1);
  if (!Number.isFinite(value)) {
    return 1;
  }
  return Math.min(1, Math.max(0.01, value));
}

