+<body>
+  <main class="app">
+    <header class="top">
+      <div>
+        <p class="eyebrow">PM logic + UI prototype</p>
+        <h1>本地 7B 管理多龙虾 Agent</h1>
+      </div>
+      <div class="status" id="statusText">Manager idle</div>
+    </header>
+
+    <section class="grid">
+      <aside class="panel">
+        <div class="panel-inner">
+          <div class="label-row">
+            <span>Local Control</span>
+            <span>Qwen 7B</span>
+          </div>
+
+          <div class="local-card">
+            <h2>本地 Manager</h2>
+            <p>只负责理解、拆分、路由、预算和审批，不直接承担复杂生成。</p>
+          </div>
+
+          <div class="input-block">
+            <label for="taskInput">用户任务</label>
+            <textarea id="taskInput">生成一个 3D H5 小游戏，检查移动端体验，并发布到 AIGames。</textarea>
+            <button class="primary" id="planButton">生成路由计划</button>
+          </div>
+
+          <div class="metric-list">
+            <div class="metric">
+              <span>复杂度</span>
+              <strong id="complexityValue">medium</strong>
+            </div>
+            <div class="metric">
+              <span>线上调用</span>
+              <strong id="apiValue">3 workers</strong>
+            </div>
+            <div class="metric">
+              <span>预算级别</span>
+              <strong id="budgetValue">normal</strong>
+            </div>
+            <div class="metric">
+              <span>审批</span>
+              <strong id="approvalValue">required</strong>
+            </div>
+          </div>
+        </div>
+      </aside>
+
+      <section class="panel canvas">
+        <div class="label-row">
+          <span>Interaction Flow</span>
+          <span>no backend</span>
+        </div>
+
+        <div class="flow">
+          <button class="flow-step active" data-step="0">
+            <b>01</b>
+            <strong>理解</strong>
+            <span>识别用户目标和交付物。</span>
+          </button>
+          <button class="flow-step" data-step="1">
+            <b>02</b>
+            <strong>拆分</strong>
+            <span>拆成 PM、Game、QA、Deploy。</span>
+          </button>
+          <button class="flow-step" data-step="2">
+            <b>03</b>
+            <strong>路由</strong>
+            <span>选择线上 Lobster 执行。</span>
+          </button>
+          <button class="flow-step" data-step="3">
+            <b>04</b>
+            <strong>汇总</strong>
+            <span>本地模型压缩和检查。</span>
+          </button>
+          <button class="flow-step" data-step="4">
+            <b>05</b>
+            <strong>审批</strong>
+            <span>发布或付费前确认。</span>
+          </button>
+        </div>
+
+        <div class="plan-board">
+          <article class="route-card">
+            <div class="route-title">
+              <h2 id="routeTitle">推荐路由</h2>
+              <span class="pill" id="routeMode">auto</span>
+            </div>
+
+            <div class="agent-list">
+              <div class="agent selected" data-agent="PM">
+                <div class="agent-mark">PM</div>
+                <div>
+                  <h3>PM Lobster</h3>
+                  <p>需求边界、验收标准、优先级。</p>
+                </div>
+                <span class="toggle"></span>
+              </div>
+              <div class="agent selected" data-agent="GAME">
+                <div class="agent-mark">GM</div>
+                <div>
+                  <h3>Game Lobster</h3>
+                  <p>H5 / 3D 游戏生成和迭代。</p>
+                </div>
+                <span class="toggle"></span>
+              </div>
+              <div class="agent selected" data-agent="QA">
+                <div class="agent-mark">QA</div>
+                <div>
+                  <h3>QA Lobster</h3>
+                  <p>移动端、可玩性、性能检查。</p>
+                </div>
+                <span class="toggle"></span>
+              </div>
+              <div class="agent selected" data-agent="DEPLOY">
+                <div class="agent-mark">DP</div>
+                <div>
+                  <h3>Deploy Lobster</h3>
+                  <p>AIGames / Vercel / GitHub 发布。</p>
+                </div>
+                <span class="toggle"></span>
+              </div>
+              <div class="agent" data-agent="RESEARCH">
+                <div class="agent-mark">RS</div>
+                <div>
+                  <h3>Research Lobster</h3>
+                  <p>调研、资料、竞品和多模态产物。</p>
+                </div>
+                <span class="toggle"></span>
+              </div>
+            </div>
