+            </div>
+            <div class="json" id="jsonPreview">
+intent: build_game
+workers: pm, game, qa, deploy
+approval: required
+next: wait_for_user
+            </div>
+          </article>
+        </div>
+      </section>
+
+      <aside class="panel">
+        <div class="panel-inner">
+          <div class="label-row">
+            <span>Policy Panel</span>
+            <span>PM Guardrails</span>
+          </div>
+
+          <div class="side-list">
+            <div class="side-item">
+              <h3>用户故事 <span class="ok">defined</span></h3>
+              <p>作为操作者，我要用本地 7B 管理多个线上 Lobster，以降低成本并保持可控。</p>
+            </div>
+            <div class="side-item">
+              <h3>验收标准 <span class="ok">visible</span></h3>
+              <p>必须能看到任务、路由、Agent、预算、风险和审批状态。</p>
+            </div>
+            <div class="side-item">
+              <h3>风险边界 <span class="risk">approval</span></h3>
+              <p>发布、覆盖、付费 API、大规模执行必须进入人工确认。</p>
+            </div>
+            <div class="side-item">
+              <h3>核心指标 <span class="ok">tracked</span></h3>
+              <p>线上调用次数、预算级别、任务成功率、审批等待时间。</p>
+            </div>
+          </div>
+
+          <div class="approval">
+            <h3>审批动作</h3>
+            <p>这里只展示 UI 状态，不会调用真实 API，也不会发布或写文件。</p>
+            <button class="ghost" id="approveButton">模拟批准</button>
+          </div>
+        </div>
+      </aside>
+    </section>
+  </main>
+
+  <script>
+    const steps = [
+      {
+        status: "Understanding request",
+        title: "识别任务",
+        text: "判断用户是否要生成、测试、发布，识别是否涉及线上 API 和审批。",
+        json: ["intent: build_game", "complexity: medium", "deliverable: html_game", "risk: publish"]
+      },
+      {
+        status: "Splitting work",
+        title: "任务拆分",
+        text: "将任务拆成需求、生成、测试、发布四段，每段交给不同线上 Lobster。",
+        json: ["steps: pm, game, qa, deploy", "parallel: false", "owner: local_7b", "state: planned"]
+      },
+      {
+        status: "Routing workers",
+        title: "路由线上 Agent",
+        text: "本地 7B 只决定谁来做，真正的复杂生成由线上模型和 skill 完成。",
+        json: ["workers: pm, game, qa, deploy", "api_policy: online_when_needed", "budget: normal", "queue: enabled"]
+      },
+      {
+        status: "Summarizing outputs",
+        title: "汇总审查",
+        text: "线上 Lobster 返回结果后，本地 7B 做压缩、冲突检查和下一步建议。",
+        json: ["merge: results", "check: conflicts", "summary: operator_ready", "next: approval"]
+      },
+      {
+        status: "Waiting approval",
+        title: "人工审批",
+        text: "涉及发布、覆盖、付费调用时暂停，等待操作者确认后继续。",
+        json: ["approval: required", "actions: publish, spend, overwrite", "state: paused", "resume_token: demo"]
+      }
+    ];
+
+    const flowButtons = document.querySelectorAll(".flow-step");
+    const statusText = document.getElementById("statusText");
+    const previewTitle = document.getElementById("previewTitle");
+    const previewText = document.getElementById("previewText");
+    const jsonPreview = document.getElementById("jsonPreview");
+    const planButton = document.getElementById("planButton");
+    const approveButton = document.getElementById("approveButton");
+    const agents = document.querySelectorAll(".agent");
+    const complexityValue = document.getElementById("complexityValue");
+    const apiValue = document.getElementById("apiValue");
+    const budgetValue = document.getElementById("budgetValue");
+    const approvalValue = document.getElementById("approvalValue");
+
+    function renderStep(index) {
+      const payload = steps[index];
+      flowButtons.forEach((button, buttonIndex) => {
+        button.classList.toggle("active", buttonIndex === index);
+      });
+      statusText.textContent = payload.status;
+      previewTitle.textContent = payload.title;
+      previewText.textContent = payload.text;
+      jsonPreview.textContent = payload.json.join("\n");
+    }
+
+    function updateAgentCount() {
+      const selected = document.querySelectorAll(".agent.selected").length;
+      apiValue.textContent = `${selected} workers`;
+      budgetValue.textContent = selected > 4 ? "high" : selected > 2 ? "normal" : "low";
+      complexityValue.textContent = selected > 3 ? "medium" : "simple";
+    }
+
+    flowButtons.forEach(button => {
+      button.addEventListener("click", () => renderStep(Number(button.dataset.step)));
+    });
+
+    agents.forEach(agent => {
+      agent.addEventListener("click", () => {
+        agent.classList.toggle("selected");
+        updateAgentCount();
+      });
+    });
+
+    planButton.addEventListener("click", () => {
+      renderStep(2);
+      approvalValue.textContent = "required";
+    });
+
+    approveButton.addEventListener("click", () => {
+      statusText.textContent = "Approved in demo";
+      approvalValue.textContent = "approved";
+      jsonPreview.textContent = ["approval: granted", "state: ready_to_execute", "note: ui_demo_only"].join("\n");
+    });
+  </script>
+</body>
+</html>
