      ];
      if (entry.prompt) lines.push(`用户: ${entry.prompt}`);
      if (entry.summary) lines.push(`总结: ${entry.summary}`);
      if (entry.output) lines.push(`详细结果: ${truncateChars(entry.output, 300)}`);
      return lines.join("\n");
    })
    .join("\n\n");
}

function fallbackSummaryText(output) {
  const firstUsefulLine = cleanCodexOutput(output)
    .split(/\r?\n/)
