def build_byte_encoder() -> dict[int, str]:
    rank_to_intbyte = [b for b in range(2**8) if chr(b).isprintable() and chr(b) != " "]
    n = 0
    byte_encoder = {b: chr(b) for b in rank_to_intbyte}
    for b in range(2**8):
        if b not in byte_encoder:
            byte_encoder[b] = chr(2**8 + n)
            n += 1
    return byte_encoder


def ensure_vocabulary_json(model_dir: Path) -> None:
    # Modern faster-whisper model snapshots include tokenizer.json. Creating a
    # GPT-2-style vocabulary.json beside it can make multilingual models look
    # English-only, so only use this legacy fallback for incomplete snapshots.
    if (model_dir / "tokenizer.json").exists():
        return

    vocabulary_path = model_dir / "vocabulary.json"
    if vocabulary_path.exists():
        return

    encoding = WHISPER_TOKENIZER.get_encoding(name="gpt2", num_languages=99)
    byte_encoder = build_byte_encoder()
    tokens = [None] * encoding.n_vocab

    for token_bytes, rank in encoding._mergeable_ranks.items():
        tokens[rank] = "".join(byte_encoder[b] for b in token_bytes)

    for token, index in encoding._special_tokens.items():
        tokens[index] = token

    if any(token is None for token in tokens):
        raise RuntimeError("vocabulary_generation_failed")

    vocabulary_path.write_text(json.dumps(tokens, ensure_ascii=False, indent=2), encoding="utf-8")


