    def token_to_id(self, token: str) -> int | None:
        return self._tokenizer.special_tokens.get(token)

    def encode(self, text: str, add_special_tokens: bool = False):
        return EncodeResult(self._tokenizer.encode(text))

    def decode(self, ids):
        return self._tokenizer.encoding.decode(list(ids))


