const server = http.createServer(async (req, res) => {
  if (req.method === "OPTIONS") {
    json(res, 200, { ok: true });
    return;
  }

  if (req.method === "GET" && req.url === "/health") {
    json(res, 200, { ok: true, status: "live", port: PORT });
    return;
  }

  if (req.method === "POST" && req.url === "/transcribe") {
    try {
      const audioBuffer = await readRequestBuffer(req);
      if (!audioBuffer.length) {
        json(res, 400, { ok: false, error: "audio_required" });
        return;
      }
      const transcript = await transcribeAudio(audioBuffer, req.headers["content-type"] || "");
      json(res, 200, { ok: true, transcript });
    } catch (error) {
      json(res, 500, { ok: false, error: String(error?.message || error) });
    }
    return;
  }

  if (req.method === "POST" && req.url === "/codex-task") {
    try {
      const raw = await readRequestBuffer(req, 1024 * 1024);
      const body = tryParseJSON(raw.toString("utf8")) || {};
      const prompt = String(body.prompt || "").trim();
      if (!prompt) {
        json(res, 400, { ok: false, error: "prompt_required" });
        return;
      }
      const historyEntries = await readVoiceHistory();
      const fastResult = fastRouteVoiceTask(prompt, historyEntries);
      const route = fastResult?.route || "codex";
      const output = fastResult?.output || await runCodexVoiceTaskWithHistory(prompt, historyEntries);
      const sessionLogPath = await createSessionLog(prompt, output);
      const summary = fastResult?.summary || await summarizeSessionLog(sessionLogPath, output);
      await appendVoiceHistory({ route, prompt, output, summary });
      const speech = await speakSummary(summary);
      json(res, 200, {
        ok: true,
        route,
        output,
        summary,
        speech,
        historyFile: VOICE_HISTORY_MD
      });
    } catch (error) {
      json(res, 500, { ok: false, error: String(error?.message || error) });
    }
    return;
  }

  if (req.method !== "POST" || req.url !== "/generate") {
    json(res, 404, { ok: false, error: "not_found" });
    return;
  }

  const auth = req.headers.authorization || "";
  const token = auth.startsWith("Bearer ") ? auth.slice("Bearer ".length).trim() : "";
  if (TOKEN && token !== TOKEN) {
    json(res, 401, { ok: false, error: "unauthorized" });
    return;
  }

  let raw = "";
  req.on("data", chunk => { raw += chunk; });
  req.on("end", async () => {
    const body = tryParseJSON(raw) || {};
    const prompt = String(body.prompt || "").trim() || "FlashPlay Game";
    const style = String(body.style || "3D卡通");
    const difficulty = String(body.difficulty || "简单");
    const title = prompt.slice(0, 24);

    generationQueue = generationQueue.catch(() => {}).then(async () => {
      try {
        const generated = await runCodex(prompt, style, difficulty);
        json(res, 200, generated);
      } catch (error) {
        json(res, 200, {
          title,
          summary: "本地 codex 当前不可用，已回退到本地模板生成。",
          html: makeFallbackHTML({ title, prompt }),
          source: "fallback-template",
          error: String(error?.message || error)
        });
      }
    });
  });
});

